<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{ $code }} — Tesla Markets</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#060607;color:#f5f5f2;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;display:grid;place-items:center;overflow:hidden}.glow{position:fixed;width:600px;height:600px;border-radius:50%;background:#e821271f;filter:blur(100px);right:-200px;top:-220px}.grid{position:fixed;inset:0;background-image:linear-gradient(#ffffff08 1px,transparent 1px),linear-gradient(90deg,#ffffff08 1px,transparent 1px);background-size:70px 70px;mask-image:linear-gradient(to bottom,transparent,#000,transparent)}main{position:relative;width:min(680px,calc(100% - 32px));padding:58px;border:1px solid #ffffff1c;border-radius:28px;background:#111113d9;box-shadow:0 35px 100px #0008}header{display:flex;justify-content:space-between;align-items:center}.logo{letter-spacing:.42em;font-weight:700}.code{font-size:11px;color:#ef3f42;border:1px solid #ef3f4255;border-radius:20px;padding:7px 10px}h1{font-size:clamp(42px,7vw,76px);line-height:.95;letter-spacing:-.065em;margin:50px 0 18px}p{color:#94949b;line-height:1.8;font-size:13px;max-width:520px}.actions{display:flex;gap:10px;margin-top:30px}a{padding:12px 17px;border-radius:10px;text-decoration:none;color:#fff;font-size:11px;border:1px solid #ffffff24}.primary{background:#ef3f42;border-color:#ef3f42}@media(max-width:550px){main{padding:35px 25px}.actions{flex-direction:column;text-align:center}}</style></head><body><div class="glow"></div><div class="grid"></div><main><header><span class="logo">TESLA</span><span class="code">ERROR {{ $code }}</span></header><h1>{{ $title }}</h1><p>{{ $description }}</p><div class="actions"><a class="primary" href="{{ url('/') }}">Return home</a><a href="{{ url()->previous() }}">Go back</a></div></main></body></html>
